-- v1.30.0: Luda's support address (support@useluda.com) in the Terms (section 13) and the Privacy notice.
-- Text-only change: the terms version is NOT bumped (no new acceptance needed). Skipped if staff already edited the text.
update public.guides set steps = replace(steps::text, 'We may update these terms; the version and date are shown here, and you will be asked to agree to important changes. Questions or complaints: Help, then New appeal in the app.', 'We may update these terms; the version and date are shown here, and you will be asked to agree to important changes. Questions or complaints: Help, then New appeal in the app, or email support@useluda.com.')::jsonb, updated_at = now()
 where slug = 'terms' and steps::text like '%' || 'We may update these terms; the version and date are shown here, and you will be asked to agree to important changes. Questions or complaints: Help, then New appeal in the app.' || '%';
update public.guides set steps = replace(steps::text, 'You can download your data in Security, turn notifications on or off, and ask the Luda team to close your account. Some records must be kept for legal and anti-fraud reasons.', 'You can download your data in Security, turn notifications on or off, and ask the Luda team to close your account. Some records must be kept for legal and anti-fraud reasons. Questions about your data: support@useluda.com.')::jsonb, updated_at = now()
 where slug = 'privacy' and steps::text like '%' || 'You can download your data in Security, turn notifications on or off, and ask the Luda team to close your account. Some records must be kept for legal and anti-fraud reasons.' || '%';
